    validate_response_schema(swagger_validator, endpoint_path_template, http_method, resp)

    # Additional non-schema checks for 200
    data = safe_json(resp)
    assert isinstance(data, dict), "Response JSON body should be an object"
    # Required fields per spec
    for k in ("org_id", "project_id", "branches"):
        assert k in data, f"Missing required key in response: {k}"
    assert isinstance(data["branches"], list), "'branches' must be an array"
    # The endpoint caps at 5000 branches by description
